import { Fragment } from "react";
import type { CSSProperties, ReactNode } from "react";
import {
  Section,
  Row,
  Column,
  Text,
  Img,
  Body,
  Head as EmailHead,
  Html,
  Preview,
  Tailwind,
} from "react-email";

import { DefaultFonts } from "@/components/email/font-default";
import { createEmailTailwindConfig } from "@/components/email/email-theme";
import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

type AvatarAlignment = "center" | "left" | "right";
const fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const AvatarShell = ({ children }: { children: ReactNode }) => (
  <Section style={{ backgroundColor: "#f1f5f9" }}>
    <Section style={{ height: "100px" }} />
    <Section
      style={{
        backgroundColor: "#fffffe",
        fontFamily,
        marginLeft: "auto",
        marginRight: "auto",
        maxWidth: "600px",
        paddingBottom: "44px",
      }}
    >
      <Section style={{ paddingLeft: "24px", paddingRight: "24px" }}>
        <Section style={{ lineHeight: "44px" }}>&zwj;</Section>
        {children}
      </Section>
    </Section>
    <Section style={{ height: "100px" }} />
  </Section>
);

const AvatarWithDetailsSection = ({
  align = "center",
  avatarUrl = emailAsset(`reviews/avatar-2.jpg`),
  email = "johnadams@example.com",
  mjmlCompensation = false,
  name = "John Adams",
}: {
  align?: AvatarAlignment;
  avatarUrl?: string;
  email?: string;
  mjmlCompensation?: boolean;
  name?: string;
}) => {
  let alignmentStyle: CSSProperties = {
    marginLeft: "auto",
    marginRight: "auto",
  };
  if (align === "left") {
    alignmentStyle = { marginRight: "auto" };
  } else if (align === "right") {
    alignmentStyle = { marginLeft: "auto" };
  }
  return (
    <AvatarShell>
      <Section
        style={{
          borderSpacing: 0,
          ...(mjmlCompensation && align === "center"
            ? { left: "1px", position: "relative" as const }
            : {}),
          ...alignmentStyle,
        }}
      >
        <Fragment>
          <Row>
            <Column style={{ verticalAlign: "top" }}>
              <Img
                alt={name}
                height={48}
                src={avatarUrl}
                style={{
                  borderRadius: "9999px",
                  maxWidth: "100%",
                  verticalAlign: "middle",
                }}
                width={48}
              />
            </Column>
            <Column style={{ width: "12px" }} />
            <Column style={{ textAlign: "left", verticalAlign: "top" }}>
              <Text
                style={{
                  color: "#030712",
                  fontFamily,
                  fontSize: "14px",
                  fontWeight: 500,
                  lineHeight: "20px",
                  margin: 0,
                }}
              >
                {name}
              </Text>
              <Text
                style={{
                  color: "#6b7280",
                  fontFamily,
                  fontSize: "14px",
                  fontWeight: 400,
                  lineHeight: "20px",
                  margin: 0,
                  whiteSpace: "nowrap",
                }}
              >
                {email}
              </Text>
            </Column>
          </Row>
        </Fragment>
      </Section>
    </AvatarShell>
  );
};

interface Avatar_AvatarWithDetailsProps {
  align?: AvatarAlignment;
  avatarUrl?: string;
  email?: string;
  name?: string;
  theme?: EmailTheme;
}

const Avatar_AvatarWithDetails = ({
  theme = defaultTheme,
  ...props
}: Avatar_AvatarWithDetailsProps) => (
  <Html>
    <EmailHead>
      <DefaultFonts />
    </EmailHead>
    <Preview>Avatar with details</Preview>
    <Tailwind config={createEmailTailwindConfig(theme)}>
      <Body style={{ backgroundColor: "#f1f5f9" }} className="m-0">
        <AvatarWithDetailsSection {...props} />
      </Body>
    </Tailwind>
  </Html>
);

Avatar_AvatarWithDetails.PreviewProps = {
  align: "center",
  avatarUrl: emailAsset("reviews/avatar-2.jpg"),
  email: "johnadams@example.com",
  name: "John Adams",
  theme: defaultTheme,
} satisfies Avatar_AvatarWithDetailsProps;

const __Avatar = Avatar_AvatarWithDetails;

export interface AvatarDetailsProps {
  theme?: Parameters<typeof __Avatar>[0]["theme"];
  avatar?: {
    name: string;
    url?: string;
  };
  name?: string;
  email?: string;
  align?: "left" | "center" | "right";
}

export const AvatarDetails = ({
  theme,
  avatar,
  name,
  email,
  align,
}: AvatarDetailsProps) => (
  <__Avatar
    align={align}
    avatarUrl={avatar?.url}
    email={email}
    name={name ?? avatar?.name}
    theme={theme}
  />
);

AvatarDetails.PreviewProps = {} satisfies AvatarDetailsProps;

const ASSET_ORIGIN = "https://www.emailcn.run";

const palettes = [
  ["4F46E5", "FFFFFF"],
  ["0F766E", "FFFFFF"],
  ["C2410C", "FFFFFF"],
  ["7E22CE", "FFFFFF"],
  ["0369A1", "FFFFFF"],
  ["BE123C", "FFFFFF"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getLabel = (path: string) => {
  const fileName = path.split("/").at(-1) ?? "emailcn";

  return fileName
    .replace(/\.[^.]+$/, "")
    .replace(/^(?:logo|badge|icon)-/, "")
    .replaceAll("-", " ")
    .replaceAll(/\b\w/g, (character) => character.toUpperCase());
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const seed = getSeed(normalizedPath);
  const hash = hashString(seed);
  const [background, foreground] =
    palettes[hash % palettes.length] ?? palettes[0];
  const [width, height] = getDimensions(normalizedPath);

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return `https://api.dicebear.com/9.x/lorelei/png?seed=${encodeURIComponent(
      seed
    )}&size=${Math.max(width, height)}&backgroundColor=${background.toLowerCase()}`;
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (
    /(?:icon|btc|eth|logo|insignia|badge-app|badge-google)/i.test(
      normalizedPath
    )
  ) {
    return `https://placehold.co/${width}x${height}/${background}/${foreground}.png?text=${encodeURIComponent(
      getLabel(normalizedPath)
    )}`;
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
